// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2017, "6-7", [{"author":"И. Иткин","question":"Квакша и кряква — это … .","choices":["мышь и лягушка","лягушка и утка","утка и рыба","рыба и ящерица","ящерица и мышь"],"key":"Б","review":["Кто квакает и крякает","«Квакша» похожа по звучанию на «квакать», а «кряква» — на «крякать». Это характерные голоса разных животных.","Квакшей называют лягушку, а кряквой — дикую утку. Они даны в варианте Б."]},{"author":"И. Рубанов","question":"Какое слово мы пропустили во фразе из «Сказок Кота-Мурлыки» Николая Вагнера? С этих самых пор пошла у нас ____, ссоры и распри.","choices":["розница","разница","рознь","розь","разлад"],"key":"В","review":["Слово рядом со ссорами","Подставим существительное после «пошла». Оно должно быть женского рода и обозначать разногласия.","«Рознь» — разлад и вражда между людьми. Она подходит к перечислению ссор и распрей."]},{"author":"Б. Иомдин","question":"Один из самых первых видов быстрой связи — телеграф. Сейчас телеграммы почти не используются, но всё же их можно отправить. Вставьте слова, которые мы пропустили в рекламе одной службы отправки поздравительных телеграмм:\nИСПОЛЬЗУЙТЕ ТЕЛЕГРАФНЫЕ СОКРАЩЕНИЯ В ВАШИХ ПОЗДРАВЛЕНИЯХ ___ МЫ УВЕРЕНЫ ___ ЧТО ЭТО ПРОИЗВЕДЕТ ВПЕЧАТЛЕНИЕ НА ВАШИХ ДРУЗЕЙ ___","choices":["ВПР, ЗПТ, ТЧК","ЗПТ, ДВТЧ, ВСКЛ","ВСКЛ, ЗПТ, ДВТЧ","ТЧК, ЗПТ, ВПР","ТЧК, ЗПТ, ВСКЛ"],"key":"Д","review":["Знаки в телеграмме","Вместо пропусков сначала расставим знаки. После призыва нужно закончить предложение точкой, а перед «что» нужна запятая.","В конце рекламного сообщения уместно восклицание. Получаем «ТЧК», «ЗПТ» и «ВСКЛ»."]},{"author":"Е. Муравенко","question":"Войти ..., прийти ..., зайти ...","choices":["… в роль, … в тупик, … в ярость","… в тупик, … в роль, … в ярость","… в тупик, … в ярость, … в роль","… в роль, … в ярость, … в тупик","… в ярость, … в тупик, … в роль"],"key":"Г","review":["Три устойчивых сочетания","Актёр может «войти в роль», то есть перевоплотиться, а разгневанный человек — «прийти в ярость».","Когда решение не находится, говорят «зайти в тупик». Порядок: в роль, в ярость, в тупик."]},{"author":"А. Пиперски","question":"После основ на мягкий согласный обычно используется соединительная гласная е: например, соль — солеварение. Однако для большинства слов, образованных от слова кровь, это неверно. Какое слово всё же соответствует общему правилу?","choices":["кров_обращение","кров_носный","кров_жадный","кров_излияние","кров_пийца"],"key":"Б","review":["Соединительная гласная","Сравним «кровообращение», «кровожадный», «кровоизлияние» и «кровопийца». После кров- в них употребляется О.","После мягкой В обычной соединительной гласной была бы Е. Она встречается в слове «кровеносный»."]},{"author":"Б. Иомдин","question":"Какое слово обычно не связано с отсутствием богатства?","choices":["бедняк","бедняга","беднота","бедность","обеднеть"],"key":"Б","review":["Кого жалеют","Бедняк небогат, «беднота» и «бедность» говорят о нехватке средств, а «обеднеть» значит стать бедным.","«Бедняга» — тот, кого жалеют из-за неприятности. Слово можно сказать и о богатом, если с ним случилась беда."]},{"author":"И. Иткин","question":"Название какой из этих стран содержит информацию о её географическом положении?","choices":["Аргентина","Венесуэла","Колумбия","Панама","Эквадор"],"key":"Д","review":["Что скрыто в названии страны","Из перечисленных имён «Эквадор» напоминает слово «экватор». По-испански ecuador и означает «экватор».","Экватор проходит через эту страну. Её имя указывает именно на географическое положение."]},{"author":"Б. Иомдин","question":"Слово гожий обычно встречается в просторечии и в некоторых диалектах. А в каком примере, скорее всего, это слово использовано по ошибке?","choices":["И Горкину нравится Денис: золотые руки, на все гожий, только вот пьяница. (И. Шмелёв)","Среди взрослых берез попадались вовсе молоденькие, гожие лишь на метлу. (Л. Леонов)","Петро ― он гожий, дюже гожий к хозяйству! (М. Шолохов)","В городе немало преступников, — сказал капитан, — каждый гожий день кого-то грабят, убивают. (А. Шатаев)","Не гожее это дело, когда старики дерутся; а вот попутал враг. (Д. Мамин-Сибиряк)"],"key":"Г","review":["Гожий или божий","«Гожий» означает «годный, пригодный, подходящий». Это видно в выражениях «на всё гожий», «гожие лишь на метлу», «гожий к хозяйству».","«Каждый гожий день» не передаёт нужное «день за днём». Устойчивое выражение «каждый божий день», так что вероятна ошибка в Г."]},{"author":"И. Иткин","question":"У какого из этих слов форма творительного падежа множественного числа обычно образуется иначе, чем у остальных?","choices":["олень","конь","лошадь","газель","карась"],"key":"В","review":["Формы творительного падежа","Говорят «оленями», «конями», «газелями» и «карасями». У всех этих форм окончание -ями.","У «лошадь» обычная форма «лошадьми» с -ьми. Она отличается, хотя существует и форма «лошадями»."]},{"author":"Б. Иомдин","question":"Какое слово нельзя повторить после дефиса и получить новое слово?","choices":["лишь","только","едва","еле","чуть"],"key":"А","review":["Повтор через дефис","Можно сказать «только-только», «едва-едва», «еле-еле» и «чуть-чуть». Повтор усиливает исходное значение.","Обычного слова «лишь-лишь» нет. «Лишь» в этом списке не удваивают таким способом."]},{"author":"О. Подлесская","question":"Шёл кораблик, о чём-то мечтал,\nВсё, что видел, на мачты мотал…\nКакое устойчивое выражение обыгрывается в стихотворении Новеллы Матвеевой?","choices":["мотать на парус","мотать на ус","мотать на ухо","мотать на верёвку","мотать на удочку"],"key":"Б","review":["Что мотают на ус","Когда кто-то внимательно наблюдает и запоминает, о нём говорят «мотает на ус». Так можно поучиться на чужом опыте.","В стихотворении кораблик словно поступает так же. Вместо уса у него мачты, поэтому образ получается забавным."]},{"author":"Е. Бикмаев","question":"Какие два слова соотносятся по смыслу не так, как остальные?","choices":["густой — гуще","пустой — пуще","чистый — чище","простой — проще","жёсткий — жёстче"],"key":"Б","review":["Пары прилагательных","«Гуще», «чище», «проще» и «жёстче» сравнивают признаки густого, чистого, простого и жёсткого.","«Пуще» означает «сильнее, больше». От «пустой» форма сравнения «пустее», поэтому пара Б устроена иначе."]},{"author":"Е. Добрушина","question":"Вася заключил пари, что за час, не используя интернета, узнает историю появления в русском языке слова пари, и побежал в библиотеку. Какой словарь ему лучше всего взять?","choices":["этимологический","орфографический","толковый","русско-французский","русско-английский"],"key":"А","review":["Какой словарь открыть","Вася ищет сведения об истории слова. Орфографический словарь подскажет написание, толковый объяснит значение, двуязычные дадут перевод.","Происхождение слов объясняет этимологический словарь. Там можно узнать, как в русском появилось «пари»."]},{"author":"Б. Иомдин","question":"В какой паре слова не родственны?","choices":["соль — солонка","масло — маслёнка","суп — супница","кофе — кофейник","чай — чашка"],"key":"Д","review":["Пары о посуде","В «солонка», «маслёнка», «супница», «кофейник» узнаются основы слов «соль», «масло», «суп» и «кофе».","«Чашка» происходит от «чаша». Из чашки можно пить чай, но слова «чай» и «чашка» не родственные."]},{"author":"И. Иткин","question":"Перед вами — цитата из сказки Антона Тилипмана «Прессница и <u>кардон</u>». Некоторые слова подчёркнуты: ...<u>Позвериться</u> на свежем воздухе <u>прессница</u> никак не могла — а всё потому, что <u>хоранял</u> её <u>блозный</u> <u>гормоный</u> <u>рёвоглохтый</u> <u>кардон</u>. Вы спросите, от кого <u>хоранял</u>? Да от всяческих <u>пнирцев</u> и <u>коровеличей</u>. А ещё от <u>фрагов</u>, <u>боранов</u> и <u>кармизов</u> — врезалось их в той <u>настре</u> — не сосчитать... Какое ещё слово также надо было бы подчеркнуть?","choices":["свежем","спросите","всяческих","врезалось","сосчитать"],"key":"Г","review":["Перепутанные буквы","Подчёркнутые слова получаются перестановкой букв обычных слов. Например, «прессница» даёт «принцесса», а «кардон» — «дракон».","«Врезалось их в той стране» по смыслу следует прочесть «развелось их в той стране». В «врезалось» переставлены те же буквы, так что его тоже нужно выделить."]},{"author":"П. Аркадьев","question":"Какие личные формы настоящего времени глаголов таить и таять пишутся одинаково, а произносятся по-разному?","choices":["никакие","только формы 1 л. ед. ч.","только формы 3 л. мн. ч.","только формы 1 л. ед. ч. и 3 л. мн. ч.","все"],"key":"Б","review":["Два ударения в «таю»","Лёд тает, поэтому «я та́ю» — форма «таять». О тайне «я таю́» — форма «таить». Буквы совпадают, ударения различаются.","В прочих формах меняются и буквы: «таешь — таишь», «тают — таят». Условие выполняется только в первом лице единственного числа."]},{"author":"А. Кухто и А. Пиперски","question":"Какое из этих слов по составу устроено иначе, чем остальные?","choices":["американец","мексиканец","африканец","албанец","спартанец"],"key":"Г","review":["Названия жителей","Американец, мексиканец, африканец и спартанец образованы от Америка, Мексика, Африка и Спарта добавлением -анец к основе.","В «албанец» сочетание «ан» уже есть в имени «Албания». К основе албан- присоединяется только -ец."]},{"author":"А. Пиперски","question":"Слова мой, твой, свой, наш и ваш могут быть формами как именительного, так и винительного падежа: например, Мой дом (им.) красивый и Он купил мой дом (вин.). А какое из этих слов гораздо реже используется как форма именительного падежа, чем как форма винительного?","choices":["мой","твой","свой","наш","ваш"],"key":"В","review":["Формы слова «свой»","«Свой» обычно указывает на принадлежность тому, кто выполняет действие. Например, «он купил свой дом»: купил он, принадлежит ему.","Такую связь проще установить у дополнения, например «свой дом» в винительном. В роли подлежащего «свой» реже употребляется, хотя возможно «своя рубашка ближе к телу»."]},{"author":"Н. Петрова","question":"Грибы лисички по-литовски называются voveraitės, что значит … .","choices":["белочки","зайчики","мишки","мышки","собачки. Примечание: ė читается примерно как русское э"],"key":"А","review":["Грибы с именем зверька","Литовское voverė означает «белка». В форме voveraitės узнаётся то же начало.","Это уменьшительное название во множественном числе: «белочки». У нас те же грибы сравнили с лисами."]},{"author":"Е. Бикмаев","question":"В басне Сергея Михалкова есть строки:\nЖивой зелёный Рак, речной пропахший тиной,\nГлазами пожирал собрата своего.\nКакое из слов в этих строках не согласуется со словом Рак?","choices":["живой","зелёный","речной","пропахший","все слова в (А) — (Г) согласуются со словом Рак"],"key":"В","review":["Что пропахло тиной","«Живой», «зелёный» и «пропахший» имеют мужской род и относятся к слову «Рак».","«Речной» здесь можно соединить со словом «тиной»: пропах речной тиной. Это форма творительного падежа женского рода."]},{"author":"А. Панина","question":"В каком из следующих сложных слов корни соотносятся друг с другом по смыслу не так, как в остальных?","choices":["бронебойный","плодоносный","мышевидный","травоядный","потогонный"],"key":"В","review":["Связь между корнями","Бронебойный пробивает броню, плодоносный приносит плоды, травоядный ест траву, потогонный вызывает пот. Везде первая основа называет объект или результат действия.","«Мышевидный» значит «похожий на мышь». Здесь первая основа задаёт образ сравнения, поэтому связь иная."]},{"author":"И. Иткин","question":"Герои сказочной повести Эриха Кестнера «Мальчик и девочка из спичечной коробки» любят придумывать разные невероятные блюда. Одно из этих блюд в русском переводе носит название «... под соусом из ахинеи». Что мы пропустили?","choices":["отбивные","жаркое","дичь","лобио","венские вафли"],"key":"В","review":["Невероятное блюдо","Слово «ахинея» обозначает бессмысленные речи. Для названия блюда подойдёт слово с кулинарным значением, которое тоже может означать бессмыслицу.","«Дичь» — мясо диких животных и птиц, а переносно — нелепость. Поэтому получается «дичь под соусом из ахинеи»."]},{"author":"П. Аркадьев","question":"Какой из этих глаголов можно понять и как глагол совершенного, и как глагол несовершенного вида?","choices":["зачитать","перечитать","прочитать","причитать","почитать"],"key":"Д","review":["Вид слова «почитать»","Если «почитать книгу» значит некоторое время читать её, это совершенный вид. Можно сказать «я хочу немного почитать».","В «почитать старших» речь об уважении, которое можно проявлять постоянно. Это несовершенный вид. Оба значения принадлежат форме «почитать»."]},{"author":"Е. Бикмаев","question":"У Корнея Ивановича Чуковского в книге «От двух до пяти» читаем: «Как бы ни была велика разница между детьми из различных социальных слоёв, как бы ни было ______ содержание их речей, в их словотворчестве это сказывается меньше всего». В пропущенном двенадцатибуквенном слове первые пять букв те же самые, что и последние пять (и стоят в том же порядке). Каковы шестая и седьмая буквы этого слова?","choices":["до","за","об","от","по"],"key":"В","review":["Одинаковые края слова","По смыслу подходит «разнообразно». Начало «разно» и конец «разно» содержат по пять одинаковых букв.","Между ними в «разно-об-разно» находятся шестая и седьмая буквы — О и Б."]},{"author":"Е. Муравенко","question":"Если в данных словах вместо звонких согласных звуков произнести парные глухие, то во всех случаях, кроме одного, получатся новые слова. Из какого слова новое слово не получится?","choices":["горка","дог","зуд","зубы","багет"],"key":"Г","review":["Глухие вместо звонких","Если оглушить нужные звуки в «горка», «дог», «зуд» и «багет», звучание совпадёт со словами «корка», «ток», «суд» и «пакет». Ударение останется на прежнем месте.","При замене в «зу́бы» получится «су́пы». Нормативная форма «супы́» имеет другое ударение, поэтому новым словом это звучание не станет."]},{"author":"П. Аркадьев","question":"Какое из слов: ванна, длинна, колонна, тонна — не существительное?","choices":["ванна","длинна","колонна","тонна","все эти слова — существительные"],"key":"Б","review":["Слова с двойной «н»","Ванна, колонна и тонна называют предметы или величины. Это существительные.","«Длинна» — краткое прилагательное женского рода от «длинный»: «дорога длинна». Оно выделяется среди остальных."]},{"author":"С. Переверзева","question":"Его можно засечь и убить, но нельзя … .","choices":["узнать","провести","опередить","отчитать","выиграть"],"key":"Г","review":["Действия со временем","Можно засечь время по часам или убить время, заняв его ожиданием. С ним сочетаются также «узнать», «провести», «опередить» и «выиграть».","«Отчитать» значит строго выговорить кому-либо. Время в этом значении отчитать нельзя."]},{"author":"И. Иткин","question":"Какое из этих слов часто встречается после предлога?","choices":["пото́м","затем","впоследствии","теперь","все эти слова почти никогда не встречаются после предлогов"],"key":"А","review":["Наречие после предлога","Остальные слова сами указывают последовательность: «затем», «впоследствии», «теперь».","С «потом» широко употребляется предлог «на»: «оставим разговор на потом». Подходит А."]},{"author":"Е. Бикмаев","question":"Четыре из пяти этих звуков могут обозначаться на письме одной и той же буквой. Найдите пятый лишний.","choices":["[в]","[ф]","[х]","[к]","[г]"],"key":"Б","review":["Что обозначает буква «г»","Г может звучать [г], на конце «друг» — [к], в «лёгкий» — [х], а в окончаниях вроде «нового» — [в].","Для [ф] такого обычного чтения буквы Г нет. Этот звук отличается от остальных."]},{"author":"М. Выжлаков","question":"На готском языке flokan ― оплакивать, faiflok ― он оплакивал, maitan ― рубить, maimait ― он рубил, slepan ― спать, aiauk ― он рос. Как будет по-готски он спал, расти?","choices":["saislep, aiaukan","seslep, iaukan","slaislep, aukan","saislop, iaukan","saislep, aukan. Примечание. Готский язык ― один из древних германских языков"],"key":"Д","review":["Формы в готском языке","В прошедшем времени перед основой появляется начальная согласная и ai: flok даёт fai-flok, mait — mai-mait. Поэтому slep даёт sai-slep.","В aiauk часть ai добавлена перед основой без начальной согласной — auk. С окончанием -an получается aukan. Подходит saislep, aukan."]}], {"year":2017,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2017-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
